"""
Kaggle GPU job: run torch/prune.py (self-check) and torch/bench.py steps on CUDA.

Kaggle script kernels upload only this one file, so torch/prune.py and
torch/bench.py are embedded below (SOURCES). Refresh them before pushing:

  python kaggle_job/bundle.py && uvx kaggle kernels push -p kaggle_job

Outputs in /kaggle/working: env.txt, selfcheck.log, bench.log,
results_steps_torch_*.json, summary.json.
"""
import json, subprocess, sys, time
from pathlib import Path

OUT = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
SRC = OUT / "src"
TRANSFORMERS = "transformers==5.17.0"  # the version the CPU self-check was verified with


def sh(cmd, log=None):
    """Run cmd, tee output to OUT/log, return (exit code, seconds)."""
    t0, lines = time.time(), []
    p = subprocess.Popen(cmd, cwd=OUT, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        print(line, end="", flush=True); lines.append(line)
    rc = p.wait()
    if log:
        (OUT / log).write_text("".join(lines))
    return rc, round(time.time() - t0, 1)


def main():
    SRC.mkdir(exist_ok=True)
    for name, text in SOURCES.items():
        (SRC / name).write_text(text)
    py = sys.executable
    summary = {"pip": sh([py, "-m", "pip", "install", "-q", TRANSFORMERS])[0]}
    sh(["bash", "-c", f"nvidia-smi; {py} -c 'import torch, transformers; "
        "print(torch.__version__, torch.version.cuda, transformers.__version__)'"], "env.txt")
    summary["env"] = (OUT / "env.txt").read_text().strip().splitlines()[-1]
    summary["selfcheck"] = dict(zip(("exit", "s"), sh([py, str(SRC / "prune.py")], "selfcheck.log")))
    summary["bench"] = dict(zip(("exit", "s"), sh([py, str(SRC / "bench.py"), "steps"], "bench.log")))
    for f in sorted(OUT.glob("results_steps_torch_*.json")):
        summary[f.name] = json.loads(f.read_text())
    (OUT / "summary.json").write_text(json.dumps(summary, indent=1))
    print(json.dumps({k: v for k, v in summary.items() if not k.endswith(".json")}, indent=1))
    sys.exit(int(summary["selfcheck"]["exit"] != 0 or summary["bench"]["exit"] != 0))


